# Parse dates and filter to the target range
start_date = datetime(2023, 1, 18)
end_date = datetime(2024, 11, 9)

def parse_date(date_str):
    """Parse date string like 'May 03, 2022'"""
    try:
        return datetime.strptime(date_str.strip(), "%b %d, %Y")
    except:
        return None

# Filter reviews in date range
filtered_reviews = []
for date_str, user, text in reviews_raw:
    parsed_date = parse_date(date_str)
    if parsed_date and start_date <= parsed_date <= end_date:
        filtered_reviews.append((date_str.strip(), user, text.strip(), parsed_date))

print(f"Reviews in date range [{start_date.date()} to {end_date.date()}]: {len(filtered_reviews)}")
print("\nFirst 5 filtered reviews:")
for i, (date_str, user, text, parsed_date) in enumerate(filtered_reviews[:5]):
    print(f"{i+1}. {date_str} | User {user} | {text[:80]}...")
print("\nLast 5 filtered reviews:")
for i, (date_str, user, text, parsed_date) in enumerate(filtered_reviews[-5:]):
    print(f"{len(filtered_reviews)-4+i}. {date_str} | User {user} | {text[:80]}...")
```

